const item = $input.first();
const bin = item.binary || {};
const keys = Object.keys(bin);
let csvKey = keys.find(k => /\.csv$/i.test(bin[k].fileName || '') || /csv/i.test(bin[k].mimeType || ''));
if (!csvKey) csvKey = keys.find(k => /csv/i.test(k));
let resumeKey = keys.find(k => k !== csvKey);
if (!csvKey || !resumeKey) {
  throw new Error('Could not find both the CSV file and the resume in the form upload. Found: ' + keys.join(', '));
}
return [{ json: { resumeFileName: bin[resumeKey].fileName }, binary: { csv: bin[csvKey], resume: bin[resumeKey] } }];

const resume = $('Identify CSV and Resume').first().binary.resume;
const emailRe = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/;
const seen = new Set();
const out = [];
for (const row of $input.all()) {
  const j = row.json || {};
  const preferredKey = Object.keys(j).find(k => /e-?mail/i.test(k));
  let value = preferredKey ? String(j[preferredKey] || '') : '';
  let match = value.match(emailRe);
  if (!match) {
    for (const v of Object.values(j)) {
      const m = String(v || '').match(emailRe);
      if (m) { match = m; break; }
    }
  }
  if (!match) continue;
  const email = match[0].trim().toLowerCase();
  if (seen.has(email)) continue;
  seen.add(email);
  out.push({ json: { email }, binary: { resume } });
}
if (out.length === 0) throw new Error('No valid email addresses found in the CSV.');
return out;
